const body = $json.body || $json;
const ALLOWED_SOURCE_TYPES = [
  'INSTALLATION_REPORT', 'SERVICE_REPORT', 'INSPECTION_REPORT', 'FAILURE_REPORT',
  'DRAWING', 'DATASHEET', 'BILL_OF_MATERIAL', 'MAINTENANCE_HISTORY',
  'PUMP_MASTER_EXCEL', 'STOCK_EXCEL', 'INSTALLATION_HISTORY_EXCEL',
  'PHOTO', 'VIDEO', 'ENGINEER_NOTE', 'CUSTOMER_NOTE'
];
const ALLOWED_VERIFICATION_STATUSES = ['DRAFT', 'UNDER_REVIEW', 'VERIFIED', 'CANONICAL'];

if (!body.knowledge_source_id) {
  throw new Error('knowledge_source_id is required');
}

if (!body.source_type || !ALLOWED_SOURCE_TYPES.includes(body.source_type)) {
  throw new Error('source_type must be one of: ' + ALLOWED_SOURCE_TYPES.join(', '));
}

if (!body.source_name) {
  throw new Error('source_name is required');
}

const verification_status = body.verification_status || 'DRAFT';
if (!ALLOWED_VERIFICATION_STATUSES.includes(verification_status)) {
  throw new Error('verification_status must be one of: ' + ALLOWED_VERIFICATION_STATUSES.join(', '));
}

if (body.file_size !== undefined && body.file_size !== null && (typeof body.file_size !== 'number' || body.file_size < 0)) {
  throw new Error('file_size must be a non-negative number');
}

return [
  {
    json: {
      knowledge_source_id: body.knowledge_source_id,
      source_type: body.source_type,
      source_name: body.source_name,
      original_file_name: body.original_file_name || null,
      source_date: body.source_date || null,
      customer: body.customer || null,
      site: body.site || null,
      unit: body.unit || null,
      uploaded_by: body.uploaded_by || null,
      upload_timestamp: body.upload_timestamp || null,
      source_url: body.source_url || null,
      verification_status,
      confidence_level: body.confidence_level ?? null,
      file_hash: body.file_hash || null,
      file_size: body.file_size ?? null,
      media_type: body.media_type || null,
      description: body.description || null
    }
  }
];

const existing = $input.first()?.json;
const input = $('Validate Knowledge Source Input').first().json;

return [{
  json: {
    ...input,
    _conflict: !!(existing && existing.knowledge_source_id)
  }
}];
